package android.graphics.drawable;public class Drawable {private android.graphics.ColorFilter filter;public android.graphics.ColorFilter getColorFilter(){return filter;}public void setColorFilter(android.graphics.ColorFilter f){filter=f;invalidateSelf();}public void clearColorFilter(){setColorFilter(null);}private int[] state=new int[0];public int[] getState(){return state;}public boolean setState(int[] value){state=value;return true;}public interface Callback {void invalidateDrawable(Drawable who);}private Callback callback;public Callback getCallback(){return callback;}public void setCallback(Callback c){callback=c;}public void invalidateSelf(){if(callback!=null)callback.invalidateDrawable(this);}private android.graphics.Rect bounds=new android.graphics.Rect();public android.graphics.Rect getBounds(){return bounds;}public void setBounds(android.graphics.Rect rect){bounds=rect;}public Drawable mutate(){return this;}}